package com.neu.riketiku.zhishikapian;
import static org.assertj.core.api.Assertions.assertThat;import com.neu.riketiku.ai.AiProviderService;import com.neu.riketiku.ai.config.AiProviderProperties;import com.neu.riketiku.ai.log.AiCallLogWriter;import com.neu.riketiku.ai.provider.*;import com.neu.riketiku.demo.DemoDataService;import com.neu.riketiku.tiku.admin.AdminQuestionIntegrationTestSupport;import java.util.ArrayDeque;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.*;import org.springframework.context.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import tools.jackson.databind.ObjectMapper;
@SpringBootTest @Import(KnowledgeCardPracticeIntegrationTest.Config.class) class KnowledgeCardPracticeIntegrationTest extends AdminQuestionIntegrationTestSupport{@Autowired DemoDataService demo;@Autowired KnowledgeCardPracticeService service;@Autowired QueueProvider provider;@Autowired JdbcTemplate jdbc;ObjectMapper mapper=new ObjectMapper();@Test @Transactional void generatesGradesAndSubmitsPendingFromReviewedCard(){demo.seed();long user=jdbc.queryForObject("SELECT id FROM yong_hu WHERE yong_hu_ming='demo_199_01'",Long.class),card=jdbc.queryForObject("SELECT h.id FROM gao_pin_kao_dian h JOIN ren_ke_guan_xi r ON r.id=h.ren_ke_guan_xi_id JOIN ban_ji b ON b.id=r.ban_ji_id WHERE b.ban_ji_bian_ma='DEMO_CLASS_199' AND h.zhuang_tai='PUBLISHED' ORDER BY h.id LIMIT 1",Long.class);provider.answers.add("{\"schemaVersion\":2,\"candidates\":[{\"stem\":\"空间站实验中需要先判断受力再联合运动条件得到结论\",\"questionType\":\"SINGLE_CHOICE\",\"difficulty\":3,\"options\":[{\"label\":\"A\",\"content\":\"先分析合力再判断加速度\",\"correct\":true},{\"label\":\"B\",\"content\":\"只观察速度方向\",\"correct\":false},{\"label\":\"C\",\"content\":\"忽略参考系\",\"correct\":false}],\"correctAnswer\":{\"schemaVersion\":1,\"type\":\"SINGLE_CHOICE\",\"optionLabels\":[\"A\"]},\"standardAnalysis\":\"新情境下先分析合力，再依据加速度与运动条件分两步判断。\",\"variationMode\":\"SCENARIO_TRANSFER\",\"variationSummary\":\"改变空间情境和条件组合\",\"changedDimensions\":[\"SCENARIO\",\"CONDITION\",\"REASONING_PATH\"]}]}");var items=service.generate(user,card,new KnowledgeCardPracticeDtos.Generate("SINGLE_CHOICE",3,"SCENARIO_TRANSFER",1));assertThat(items).hasSize(1);assertThat(items.getFirst().correctAnswer()).isNull();var answered=service.answer(user,items.getFirst().id(),mapper.readTree("\"A\""));assertThat(answered.correct()).isTrue();assertThat(answered.aiAnalysis()).isNotBlank();assertThat(service.submit(user,answered.id()).status()).isEqualTo("SUBMITTED_REVIEW");assertThat(jdbc.queryForObject("SELECT zhuang_tai FROM ti_mu WHERE id=?",String.class,answered.questionId())).isEqualTo("PENDING");}
@Test void instanceFailureRollsBackCandidateQualityAndSuccess(){demo.seed();long user=jdbc.queryForObject("SELECT id FROM yong_hu WHERE yong_hu_ming='demo_199_01'",Long.class),card=jdbc.queryForObject("SELECT h.id FROM gao_pin_kao_dian h JOIN ren_ke_guan_xi r ON r.id=h.ren_ke_guan_xi_id JOIN ban_ji b ON b.id=r.ban_ji_id WHERE b.ban_ji_bian_ma='DEMO_CLASS_199' AND h.zhuang_tai='PUBLISHED' ORDER BY h.id LIMIT 1",Long.class);provider.answers.add("{\"schemaVersion\":2,\"candidates\":[{\"stem\":\"月球车实验中先比较受力条件再通过两步推理得到运动结论\",\"questionType\":\"SINGLE_CHOICE\",\"difficulty\":3,\"options\":[{\"label\":\"A\",\"content\":\"先确定参考系和合力\",\"correct\":true},{\"label\":\"B\",\"content\":\"只替换数值即可\",\"correct\":false},{\"label\":\"C\",\"content\":\"忽略运动状态\",\"correct\":false}],\"correctAnswer\":{\"schemaVersion\":1,\"type\":\"SINGLE_CHOICE\",\"optionLabels\":[\"A\"]},\"standardAnalysis\":\"新情境要求先确定参考系，再联立合力和运动状态完成两步判断。\",\"variationMode\":\"CONDITION_RECOMBINATION\",\"variationSummary\":\"重组实验条件和推理路径\",\"changedDimensions\":[\"SCENARIO\",\"CONDITION\",\"REASONING_PATH\"]}]}");String trigger="fail_card_instance_"+java.util.UUID.randomUUID().toString().replace("-","").substring(0,8);jdbc.execute("CREATE TRIGGER "+trigger+" BEFORE INSERT ON zhi_shi_ka_pian_lian_xi_shi_li FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='forced card instance failure'");try{org.assertj.core.api.Assertions.assertThatThrownBy(()->service.generate(user,card,new KnowledgeCardPracticeDtos.Generate("SINGLE_CHOICE",3,"CONDITION_RECOMBINATION",1))).isInstanceOfSatisfying(com.neu.riketiku.renzheng.RenZhengYeWuYiChang.class,e->assertThat(e.getCode()).isEqualTo("AI_GENERATION_FAILED"));}finally{jdbc.execute("DROP TRIGGER IF EXISTS "+trigger);}long task=jdbc.queryForObject("SELECT MAX(id) FROM ai_sheng_cheng_ren_wu WHERE chuang_jian_ren_id=?",Long.class,user);assertThat(jdbc.queryForObject("SELECT zhuang_tai FROM ai_sheng_cheng_ren_wu WHERE id=?",String.class,task)).isEqualTo("FAILED");assertThat(jdbc.queryForObject("SELECT yi_sheng_cheng_shu_liang FROM ai_sheng_cheng_ren_wu WHERE id=?",Integer.class,task)).isZero();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM ai_hou_xuan_ti_zhi_liang_ping_jia WHERE ai_sheng_cheng_ren_wu_id=?",Integer.class,task)).isZero();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM zhi_shi_ka_pian_lian_xi_shi_li WHERE ai_sheng_cheng_ren_wu_id=?",Integer.class,task)).isZero();}
@TestConfiguration static class Config{@Bean @Primary QueueProvider provider(AiProviderProperties p,AiModelProvider actual,AiCallLogWriter log){return new QueueProvider(p,actual,log);}}static class QueueProvider extends AiProviderService{final ArrayDeque<String>answers=new ArrayDeque<>();QueueProvider(AiProviderProperties p,AiModelProvider a,AiCallLogWriter l){super(p,a,l);}@Override public AiModelResult generate(AiModelRequest r){return new AiModelResult("fake-deepseek","test-model",answers.removeFirst(),new AiTokenUsage(1,1,2),"stop");}}
}
